-- deployment-mode: rolling
-- Validate the foreign keys 0926 and 0927 re-added NOT VALID. Every existing
-- row already satisfied the same reference under the previous constraint, so
-- validation only proves it again. VALIDATE CONSTRAINT takes SHARE UPDATE
-- EXCLUSIVE on the referencing table and ROW SHARE on the referenced one, so
-- reads and writes continue while it scans.
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60min';

